// The Webhook node has already verified the HS256 signature and expiry with the
// "LendLoop: Convex -> n8n signing key" credential. It doesn't check the issuer,
// the audience or the payload, so that happens here. Only verified claims are used.
const claims = $json.jwtPayload ?? {};
const event = claims.event ?? {};

const isDay = (d) => typeof d === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(d);
const isEmail = (e) => typeof e === 'string' && e.length <= 254 && /^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(e);
const day = (d) =>
  new Date(d + 'T00:00:00Z').toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short', timeZone: 'UTC' });

const problems = [];
if (claims.iss !== 'lendloop-convex') problems.push('issuer');
if (claims.aud !== 'lendloop-n8n') problems.push('audience');
if (claims.kind !== 'loan_event') problems.push('kind');
if (typeof claims.jti !== 'string' || claims.jti.length === 0) problems.push('jti');
if (!isEmail(event.recipient?.email)) problems.push('recipient');
if (!isDay(event.loan?.startDate) || !isDay(event.loan?.endDate)) problems.push('dates');

const other = event.counterpart?.name ?? 'A neighbour';
const tool = event.tool?.name ?? 'a tool';
const dates = problems.includes('dates') ? '' : day(event.loan.startDate) + ' to ' + day(event.loan.endDate);
const reason = event.loan?.reason ? '\n\nReason: ' + event.loan.reason : '';
const templates = {
  'loan.requested': {
    subject: other + ' would like to borrow your ' + tool,
    body: other + ' would like to borrow your ' + tool + ' from ' + dates + '.\n\nApprove or decline the request:\n' + event.link,
  },
  'loan.approved': {
    subject: 'Approved: ' + tool + ' from ' + other,
    body: other + ' approved your request to borrow their ' + tool + ' from ' + dates + ".\n\nYou can now see each other's email in LendLoop to arrange the hand-over:\n" + event.link,
  },
  'loan.declined': {
    subject: 'Your request for the ' + tool + ' was declined',
    body: other + " can't lend you their " + tool + ' from ' + dates + '.' + reason + '\n\nThere may be another one on the board:\n' + event.link,
  },
  'loan.cancelled': {
    subject: other + ' cancelled their request for your ' + tool,
    body: other + ' no longer needs your ' + tool + ' from ' + dates + '. There is nothing else to do.\n\n' + event.link,
  },
  'loan.returned': {
    subject: 'Thanks for returning the ' + tool,
    body: other + ' marked their ' + tool + ' as returned. Thanks for borrowing kindly!\n\n' + event.link,
  },
};
const template = templates[event.type];
if (!template) problems.push('type');
if (problems.length > 0) return [{ json: { valid: false, problems } }];

// Convex retries until it gets a 2xx, so the same event (same jti) can arrive twice.
const alreadySent = Boolean(($getWorkflowStaticData('global').sentEventIds ?? {})[claims.jti]);

// Pass on only what the email needs.
return [{
  json: {
    valid: true,
    duplicate: alreadySent,
    eventId: claims.jti,
    type: event.type,
    to: event.recipient.email,
    subject: template.subject,
    text: 'Hi ' + (event.recipient.name ?? 'neighbour') + ',\n\n' + template.body + '\n\n– LendLoop',
  },
}];

const event = $('Check claims and build email').first().json;
const raw = $json.error;
const error = raw === undefined ? undefined : typeof raw === 'string' ? raw : (raw.message ?? JSON.stringify(raw));

if (!error) {
  // Remember sent event IDs for a week so a redelivery isn't emailed twice.
  const store = $getWorkflowStaticData('global');
  const sent = store.sentEventIds ?? {};
  const weekAgo = Date.now() - 7 * 24 * 60 * 60 * 1000;
  for (const [id, at] of Object.entries(sent)) if (at < weekAgo) delete sent[id];
  sent[event.eventId] = Date.now();
  store.sentEventIds = sent;
}
return [{ json: { eventId: event.eventId, type: event.type, status: error ? 'failed' : 'sent', error } }];
